mapper.insert:
INSERT INTO T_STOCK_PRICE
( STOCK_ID
,TRADE_DATE
,OPEN_PRICE
,HIGH_PRICE
,LOW_PRICE
,CLOSE_PRICE
,VOLUME
) VALUES (
#{stockId}
,#{tradeDate}
,#{openPrice}
,#{highPrice}
,#{lowPrice}
,#{closePrice}
,#{volume}
)
ON CONFLICT (STOCK_ID, TRADE_DATE) DO UPDATE
SET  OPEN_PRICE  = EXCLUDED.OPEN_PRICE
,HIGH_PRICE  = EXCLUDED.HIGH_PRICE
,LOW_PRICE   = EXCLUDED.LOW_PRICE
,CLOSE_PRICE = EXCLUDED.CLOSE_PRICE
,VOLUME      = EXCLUDED.VOLUME
,UPT_DAY     = NOW()

INSERT INTO T_STOCK (
       SYMBOL
      ,NAME
      ,MARKET
      ,SECURITY_TYPE
      ,USE_YN
) VALUES (
       #{symbol}
      ,#{name}
      ,#{market}
      ,#{securityType}
      ,'Y'
)
ON CONFLICT (SYMBOL) DO UPDATE
   SET NAME          = EXCLUDED.NAME
      ,MARKET        = EXCLUDED.MARKET
      ,SECURITY_TYPE = EXCLUDED.SECURITY_TYPE
      ,UPT_DAY       = NOW()

mapper.update:
UPDATE T_STOCK
   SET SHARES_OUTSTANDING = #{sharesOutstanding}
 WHERE 1=1
   AND ID = #{stockId}
